#include <iostream>

int main() {
    // Row dimension omitted; compiler infers m = 2
    // Partial initialization ensures unspecified elements become 0.0
    float A[][3] = {
        {1.5f, 2.5f},
        {4.0f}
    };

    constexpr int rows = 2;
    constexpr int cols = 3;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            std::cout << A[i][j] << (j + 1 == cols ? "" : " ");
        }
        std::cout << "\n";
    }

    // Verify row-major linear memory layout
    const float* flat_ptr = &A[0][0];
    std::cout << "Linear view:";
    for (int k = 0; k < rows * cols; ++k) {
        std::cout << " " << *(flat_ptr + k);
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int m, n;
    if (!(std::cin >> m >> n)) return 0;

    float a[10][10];
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cin >> a[i][j];
        }
    }

    // Find maximum element and its coordinates
    float amax = a[0][0];
    int imax = 0, jmax = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] > amax) {
                amax = a[i][j];
                imax = i;
                jmax = j;
            }
        }
    }

    // Output formatted matrix
    std::cout << "Ma tran da nhap:\n";
    std::cout << std::fixed << std::setprecision(1);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cout << std::setw(6) << a[i][j];
        }
        std::cout << "\n";
    }

    std::cout << "So lon nhat la " << std::setw(6) << amax << "\n";
    std::cout << "tai vi tri (" << imax << "," << jmax << ")\n";

    return 0;
}
